parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reasoning": {
      "type": "string",
      "description": "Explicación breve (1-2 frases) de por qué se eligieron estas herramientas, basándose en la consulta del usuario y las Reglas de Decisión."
    },
    "tools": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "Base_de_Conocimiento_Arrojo",
          "Spotify",
          "Facebook",
          "YouTube",
          "Wikipedia",
          "None"
        ]
      },
      "description": "Lista de las herramientas obligatorias a utilizar. Usar ['None'] solo si la consulta es charla casual o un saludo."
    }
  },
  "required": [
    "reasoning",
    "tools"
  ]
}
